# ---- icons (24px grid, stroked) ------------------------------------------------
def _sun():
    """Disc with eight rays."""
    rays = ""
    for i in range(8):
        a = i * math.pi / 4
        s, c = math.sin(a), math.cos(a)
        rays += f"M{12 + 7 * s:.2f},{12 - 7 * c:.2f}L{12 + 9.5 * s:.2f},{12 - 9.5 * c:.2f}"
    return "M12 16a4 4 0 1 0 0-8 4 4 0 0 0 0 8z" + rays


