def get_status(hour):
    return next(text for lo, hi, text in STATUSES if lo <= hour < hi)


def get_weather(hour):
    try:
        req = Request(
            "https://wttr.in/Hyderabad?format=j1",
            headers={"User-Agent": "README-refresh/1.0"},
        )
        with urlopen(req, timeout=15) as response:
            current = json.loads(response.read())["current_condition"][0]
        condition = current["weatherDesc"][0]["value"].strip()
        return {
            "location": "Hyderabad",
            "temperature": f"{current['temp_C']}°C",
            "condition": condition,
            "icon": weather_icon(condition, hour),
        }
    except SOFT_ERRORS:
        return {"location": "Hyderabad", "temperature": None, "condition": "unavailable", "icon": "cloud"}


def get_repositories():
    repos, page = [], 1
    while True:
        data = github_get(
            f"{API}/users/{USERNAME}/repos?per_page=100&page={page}&type=owner&sort=pushed"
        )
        repos.extend(data)
        if len(data) < 100:
            break
        page += 1
    return [repo for repo in repos if not repo["fork"] and not repo["archived"]]


def get_languages(repos):
    """Top 5 languages by bytes, as (name, percent of all code)."""
    totals = Counter()
    for repo in repos:
        try:
            totals.update(github_get(repo["languages_url"]))
        except SOFT_ERRORS as e:
            print(f"Could not read languages for {repo['name']}: {e}")
    total = sum(totals.values()) or 1
    return [(lang, round(100 * size / total, 1)) for lang, size in totals.most_common(5)]


def find_commit(full_name, sha=None, branch=None):
    """The commit behind a push: the exact head when known, else the user's
    newest commit on that branch (or the default branch)."""
    base = f"{API}/repos/{full_name}/commits"
    if sha:
        try:
            return github_get(f"{base}/{sha}")
        except SOFT_ERRORS as e:
            print(f"Could not read commit {sha[:7]} of {full_name}: {e}")
    query = f"?per_page=1&author={USERNAME}"
    if branch:
        query += f"&sha={quote(branch, safe='')}"
    try:
        items = github_get(base + query)
        return items[0] if items else None
    except SOFT_ERRORS as e:
        print(f"Could not list commits of {full_name}: {e}")
        return None


def get_latest_push(repos):
    """Most recent public push by the user, with its commit message.

    Since Oct 2025 the Events API no longer ships commit details in PushEvent
    payloads, so the message is always looked up through the commits API.
    The profile repo (EXCLUDED_REPO) is skipped everywhere. Falls back to the
    most recently pushed other repo if events are unavailable.
    """
    push = None
    try:
        events = github_get(f"{API}/users/{USERNAME}/events/public?per_page=100")
        for event in events:
            if event.get("type") != "PushEvent" or is_excluded(event["repo"]["name"]):
                continue
            body = event.get("payload") or {}
            push = {
                "repo": event["repo"]["name"],
                "date": event.get("created_at"),
                "sha": body.get("head"),
                "branch": (body.get("ref") or "").removeprefix("refs/heads/") or None,
            }
            break
    except SOFT_ERRORS as e:
        print(f"Could not read push events: {e}")

    if push is None:
        candidates = [repo for repo in repos if not is_excluded(repo["name"])]
        if not candidates:
            return {"repo": None, "date": None, "message": None, "branch": None, "sha": None}
        latest = max(candidates, key=lambda repo: repo.get("pushed_at") or "")
        push = {
            "repo": latest["full_name"],
            "date": latest.get("pushed_at"),
            "sha": None,
            "branch": latest.get("default_branch"),
        }

    commit = find_commit(push["repo"], push["sha"], push["branch"])
    message = None
    if commit:
        lines = (commit["commit"].get("message") or "").strip().splitlines()
        message = lines[0].strip() if lines else None
        push["sha"] = commit.get("sha")

    push["repo"] = push["repo"].split("/", 1)[-1]
    push["sha"] = (push["sha"] or "")[:7] or None
    push["message"] = message
    return push


def get_repo_stats(repos):
    """Total repo count, total stars, and the most-starred repo."""
    stars = sum(repo.get("stargazers_count", 0) for repo in repos)
    top = max(repos, key=lambda repo: repo.get("stargazers_count", 0), default=None)
    best = None
    if top and top.get("stargazers_count", 0) > 0:
        best = {"name": top["name"], "stars": top["stargazers_count"]}
    return {"total_repos": len(repos), "total_stars": stars, "most_starred_repo": best}


def get_activity():
    """Commits in the last 7 days (profile repo excluded), open issues/PRs, merged PRs."""
    since = (datetime.now(timezone.utc) - timedelta(days=7)).strftime("%Y-%m-%dT%H:%M:%SZ")
    query = """
    query($login: String!, $since: DateTime!) {
      user(login: $login) {
        contributionsCollection(from: $since) {
          commitContributionsByRepository(maxRepositories: 100) {
            repository { name owner { login } }
            contributions { totalCount }
          }
        }
        issues(states: OPEN) { totalCount }
        pullRequests(states: OPEN) { totalCount }
        merged: pullRequests(states: MERGED) { totalCount }
      }
    }
    """
    user = github_graphql(query, {"login": USERNAME, "since": since})["user"]
    commits = sum(
        entry["contributions"]["totalCount"]
        for entry in user["contributionsCollection"]["commitContributionsByRepository"]
        if not is_excluded(entry["repository"]["name"])
    )
    return {
        "commits_last_7_days": commits,
        "open_issues": user["issues"]["totalCount"],
        "open_prs": user["pullRequests"]["totalCount"],
        "merged_prs": user["merged"]["totalCount"],
    }


def get_contribution_stats():
    """Streaks, last-year total, and the last 30 days of daily counts.

    The contribution calendar can't be filtered per repo, so these include
    every repo GitHub credits to the account.
    """
    query = """
    query($login: String!) {
      user(login: $login) {
        contributionsCollection {
          contributionCalendar {
            totalContributions
            weeks { contributionDays { date contributionCount } }
          }
        }
      }
    }
    """
    calendar = github_graphql(query, {"login": USERNAME})["user"][
        "contributionsCollection"
    ]["contributionCalendar"]
    days = sorted(
        (day for week in calendar["weeks"] for day in week["contributionDays"]),
        key=lambda day: day["date"],
    )
    counts = [day["contributionCount"] for day in days]

    longest = run = 0
    for count in counts:
        run = run + 1 if count > 0 else 0
        longest = max(longest, run)

    current = 0
    for count in reversed(counts):
        if count == 0:
            break
        current += 1

    return {
        "current_streak": current,
        "longest_streak": longest,
        "contributions_1y": calendar["totalContributions"],
        "daily_contributions_30d": counts[-30:],
    }


def ago(iso):
    if not iso:
        return None
    delta = datetime.now(timezone.utc) - datetime.fromisoformat(iso.replace("Z", "+00:00"))
    minutes = int(delta.total_seconds() // 60)
    for unit, size in (("d", 1440), ("h", 60)):
        if minutes >= size:
            return f"{minutes // size}{unit} ago"
    return f"{max(minutes, 0)}m ago"


def fmt(value, suffix=""):
    if value is None:
        return "–"
    num = f"{value:,}" if isinstance(value, int) else value
    return f"{num}{suffix}"


