def soft(fn, fallback, what):
    """Run fn(); on a soft failure, log it and return fallback."""
    try:
        return fn()
    except SOFT_ERRORS as e:
        print(f"Could not read {what}: {e}")
        return fallback


def collect():
    """Gather every live value into the dict that drives the SVG and the JSON block."""
    now = datetime.now(IST)
    repos = get_repositories()
    langs = get_languages(repos)
    push = get_latest_push(repos)

    calendar = soft(get_contribution_stats, {
        "current_streak": None, "longest_streak": None,
        "contributions_1y": None, "daily_contributions_30d": [],
    }, "contribution stats")
    activity = soft(get_activity, {
        "commits_last_7_days": None, "open_issues": None, "open_prs": None, "merged_prs": None,
    }, "activity")

    return now, {
        "status": get_status(now.hour),
        "weather": get_weather(now.hour),
        "github": {
            "top_languages": [lang for lang, _ in langs],
            "language_share": dict(langs),
            "latest_active_repo": push["repo"],
            "last_commit": push["date"],
            "last_commit_message": push["message"],
            "last_commit_branch": push["branch"],
            "last_commit_sha": push["sha"],
            **calendar,
            **activity,
            **get_repo_stats(repos),
        },
        "updated": now.strftime("%Y-%m-%d %H:%M IST"),
    }


def main():
    parser = argparse.ArgumentParser(description="Refresh README.md and assets/status-*.svg")
    parser.add_argument(
        "--test",
        action="store_true",
        help="use sample data (no network, no token) and write to ./test-out/ only",
    )
    args = parser.parse_args()

    if args.test:
        out = Path("test-out")
        out.mkdir(exist_ok=True)
        (out / "status.svg").write_text(render_svg(SAMPLE), encoding="utf-8")
        print(f"Wrote {out / 'status.svg'}")
        return

    if not TOKEN:
        raise SystemExit("GH_PAT is not set (use --test to try it with sample data)")

    now, output = collect()

    # GitHub's image proxy caches by URL, so each refresh gets a new file name.
    ASSETS.mkdir(exist_ok=True)
    for old in ASSETS.glob("status*.svg"):
        old.unlink()
    svg_path = ASSETS / f"status-{now.strftime('%Y%m%d-%H%M')}.svg"
    svg_path.write_text(render_svg(output), encoding="utf-8")

    with open(README, "w", encoding="utf-8") as f:
        f.write(f"![Live status]({svg_path.as_posix()})\n\n")
        # Hidden from the rendered page; the website reads this block.
        f.write("<!--\n```json\n")
        json.dump(output, f, indent=2, ensure_ascii=False)
        f.write("\n```\n-->\n")


if __name__ == "__main__":
    main()
